const isModifiedEvent = event => !!(event.metaKey || event.altKey || event.ctrlKey || event.shiftKey);
const isLeftClickEvent = event => event.button === 0;
export const toLocationObject = to => typeof to === 'string' ? {
  pathname: to
} : to;
export const reactRouterNavigate = (history, to, onClickCallback) => ({
  href: history.createHref(toLocationObject(to)),
  onClick: reactRouterOnClickHandler(history, toLocationObject(to), onClickCallback)
});
export const reactRouterOnClickHandler = (history, to, onClickCallback) => event => {
  if (onClickCallback) {
    onClickCallback(event);
  }
  if (event.defaultPrevented) {
    return;
  }
  if (event.target.getAttribute('target')) {
    return;
  }
  if (isModifiedEvent(event) || !isLeftClickEvent(event)) {
    return;
  }

  // prevents page reload
  event.preventDefault();
  history.push(toLocationObject(to));
};
export const getScopedBreadcrumbs = (crumbs = [], appHistory) => {
  const wrapBreadcrumb = (item, scopedHistory) => ({
    ...item,
    ...(item.href ? reactRouterNavigate(scopedHistory, item.href) : {})
  });
  return crumbs.map(item => wrapBreadcrumb(item, appHistory));
};